(* [comment removed for export] *)
Section Run.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (so os V2 cls r SM g : Z) (x0 : PM.vstr) (dp : Z).
Local Notation sp := (V2 + cls).
Local Notation spc := (V2 - 128).
Local Notation W := (VA.ERRNO_W (pa_tp AD)).
Local Notation WT := ((os, 24) :: VA.ERRNO_W (pa_tp AD)).
Local Notation BX0 := (PM.vs_own x0).
Local Notation SCR := VA.DGT_SCR.
Local Notation NEED := VA.DGT_N.
Local Notation MAX := VA.DG_MAX.
Local Notation POST := (fun R' : bvmap 5 word => getr R' 10%bv = Z_to_bv 64 1).
Local Notation HVL := (PMSPA.HV L ar).
Hypothesis Hcls : cls = 0 \/ cls = 16.
Hypothesis V32 : V2 mod 32 = 0.
Hypothesis HH : ri_inv HI (BX0 ++ LB) FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : VA.entryAs AD L ar R M sp r SCR.
Hypothesis FRM : VA.ffroomN NEED FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis A10 : getr R (reg 10) = Z_to_bv 64 dp.
Hypothesis Hdp : 0 <= dp < 256.
Hypothesis A11 : getr R (reg 11) = Z_to_bv 64 so.
Hypothesis RSO : VA.rcellA ar M sp so 8.
Hypothesis SO8 : so mod 8 = 0.
Hypothesis CSO : L5.u64_at RSEGS M so os.
Hypothesis APSO : so + 8 <= os \/ os + 24 <= so.
Hypothesis AOS : PMSPA.aobjA FF os 24.
Hypothesis OS8 : os mod 8 = 0.
Hypothesis KS0 : kstr_at M os x0.
Hypothesis KOK0 : PQMA.ks_ok SM x0 g.
Hypothesis SMX : SM <= PQASA.SMMAX.
Hypothesis SZ0 : PM.vs_size x0 + MAX <= SM.
Hypothesis BASE : PMSTA.base_okA RSEGS AD M.
Hypothesis CR0 : PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HVL SM x0 g)) cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
    regs_preserved R R' -> POST R' -> kstr_at M' os x' -> PQMA.ks_ok SM x' g' ->
    PM.vs_size x0 <= PM.vs_size x' <= PM.vs_size x0 + MAX ->
    L5CA.ahpres L ar LB FF sp SCR WT M M' ->
    PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks HVL SM x0 g)) (PMSPA.scA L (PQMA.pot_ks HVL SM x' g')) ->
    model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
    ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

Local Notation OWN := (own10 sp R).
Local Notation OC := (ocell10 sp).

Lemma sp_facts : 140735332501888 <= V2 /\ V2 + cls <= 140737488355328 /\ (V2 + cls) mod 16 = 0 /\ 0 <= r < 2 ^ 47 /\ r mod 2 = 0
