Lemma FIN n M5 model5 LK5 Aw5 x g5 cr5 (fx5 : FPState) R5 :
  UINV n M5 model5 LK5 Aw5 x g5 cr5 -> 0 <= n <= MAX -> RC R5 ->
  getr R5 (reg 10) = Z_to_bv 64 1 -> getr R5 (reg 18) = Z_to_bv 64 F -> getr R5 (reg 23) = Z_to_bv 64 F -> getr R5 (reg 22) = Z_to_bv 64 shF ->
