(* [comment removed for export] *)
Lemma ZPUSH n M3 model3 LK3 Aw3 x g3 cr3 (fx3 : FPState) R3 (pc ra c s8v : Z)
  (PC : forall fx R MV, getr R (reg 2) = Z_to_bv 64 spc -> getr R (reg 19) = Z_to_bv 64 so -> getr R (reg 24) = Z_to_bv 64 s8v ->
        140735332487168 <= so <= 140737488355320 -> VASDGTP2.aligned so 8 -> L5KA.zeros_at MV (so / 8 + 2147450880) 1 -> L5.u64_at RSEGS MV so os ->
        7036928 <= os <= 140737488355304 ->
        exists (fx' : FPState) (R' : bvmap 5 word), msteps RSEGS (L5SAR.st fx R pc MV) (L5SAR.st fx' R' PBPC MV)
          /\ (forall j, In j [2; 3; 4; 25; 26; 27; 8; 9; 19; 20; 18; 23; 22]%nat -> getr R' (reg j) = getr R (reg j))
          /\ getr R' (reg 1) = Z_to_bv 64 ra /\ getr R' (reg 10) = Z_to_bv 64 os /\ getr R' (reg 11) = Z_to_bv 64 c /\ getr R' (reg 24) = Z_to_bv 64 (so / 8 + 2147450880)) :
  UINV n M3 model3 LK3 Aw3 x g3 cr3 -> 0 <= n < MAX -> RC R3 -> L5.ra_ok ra -> 0 <= c < 128 ->
  getr R3 (reg 24) = Z_to_bv 64 s8v ->
  getr R3 (reg 18) = Z_to_bv 64 F -> getr R3 (reg 23) = Z_to_bv 64 F -> getr R3 (reg 22) = Z_to_bv 64 shF ->
  (forall (fx6 : FPState) R6 M6 model6 LK6 Aw6 x6 g6 cr6,
      UINV (n + 1) M6 model6 LK6 Aw6 x6 g6 cr6 -> RC R6 -> getr R6 (reg 24) = Z_to_bv 64 (so / 8 + 2147450880) ->
      getr R6 (reg 18) = Z_to_bv 64 F -> getr R6 (reg 23) = Z_to_bv 64 F -> getr R6 (reg 22) = Z_to_bv 64 shF ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx6 R6 ra M6 model6) K) ->
