(* [comment removed for export] *)
Section Run.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (so os V2 cls r SM g : Z) (x0 : PM.vstr) (bs0 : list Z) (o dp : Z).
Local Notation sp := (V2 + cls).
Local Notation spc := (V2 - 96).
Local Notation W := (VA.ERRNO_W (pa_tp AD)).
Local Notation WT := ((os, 24) :: VA.ERRNO_W (pa_tp AD)).
Local Notation BX0 := (PM.vs_own x0).
Local Notation SCR := VA.WD_SCR.
Local Notation NEED := VA.WD_N.
Local Notation MAX := WD.WD_MAX.
Local Notation POST := (fun _ : bvmap 5 word => True).
Local Notation HVL := (PMSPA.HV L ar).
Hypothesis Hcls : cls = 0 \/ cls = 16.
Hypothesis V32 : V2 mod 32 = 0.
Hypothesis HH : ri_inv HI (BX0 ++ LB) FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : VA.entryAs AD L ar R M sp r SCR.
