Lemma tush_of_VA (M : word -> option byte) (buf : Z) :
  VA.IMG_HI_A <= buf -> buf + WDL.SNP_BUF <= 2 ^ 47 -> buf mod 64 = 32 -> VA.bigapart buf WDL.SNP_BUF ->
  L5.u64_at rsegs M (buf / 8 + SB - 4) VA.LRZ_QWORD -> L5KA.zeros_at M (buf / 8 + SB) 4 -> WAI.tush M buf.
Proof.
